<script setup>
import { computed,ref,onMounted } from 'vue';
import { useRoute } from 'vue-router';
import { api,errorMessage } from '../api';
import { settings,money } from '../store';
const route=useRoute();const report=ref(null);const error=ref('');const busy=ref(false);const preset=ref('30');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:settings.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const from=ref('');const to=ref(today());
const grouping=ref('daily');
const graphDays=computed(()=>{const groups=new Map();for(const day of report.value?.daily_sales || []){const date=new Date(day.date+'T12:00:00');let key=day.date;if(grouping.value==='monthly')key=day.date.slice(0,7);if(grouping.value==='weekly'){date.setDate(date.getDate()-(date.getDay()+6)%7);key=dateString(date);}const item=groups.get(key)||{date:key,revenue:0,orders:0};item.revenue+=Number(day.revenue);item.orders+=day.orders;groups.set(key,item);}return [...groups.values()];});
const isReports=computed(()=>route.path.endsWith('/reports'));
function dateString(value){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;}
function selectRange(){const now=new Date(`${today()}T12:00:00`);to.value=dateString(now);const start=new Date(now);if(preset.value==='today'){}else if(preset.value==='yesterday'){start.setDate(start.getDate()-1);to.value=dateString(start);}else if(preset.value==='month'){start.setDate(1);}else if(preset.value==='last-month'){start.setDate(1);start.setMonth(start.getMonth()-1);const end=new Date(now.getFullYear(),now.getMonth(),0,12);to.value=dateString(end);}else if(preset.value==='year'){start.setMonth(0,1);}else if(preset.value!=='custom'){start.setDate(start.getDate()-Number(preset.value)+1);}else{return;}from.value=dateString(start);load();}
async function load(){busy.value=true;error.value='';try{report.value=(await api.get('/admin/reports',{params:{from:from.value,to:to.value}})).data.data;}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
const maxRevenue=computed(()=>Math.max(1,...graphDays.value.map(day=>Number(day.revenue))));
const metrics=computed(()=>!report.value ? [] : isReports.value ? [['Revenue',money(report.value.revenue),'Fulfilled orders'],['Orders',report.value.orders,'In this date range'],['Cash collected',money(report.value.cash_collected),'Recorded as paid'],['Cancelled',report.value.cancelled,'In this date range']] : [['Today’s orders',report.value.today_orders,'Fresh from the kitchen'],['Today’s revenue',money(report.value.today_revenue),'Fulfilled today'],['Pending orders',report.value.pending,'Waiting for confirmation'],['Preparing',report.value.preparing,'In the kitchen'],['Delivered / completed',report.value.delivered,'In the selected period'],['Customers',report.value.customers,'Your growing community'],['Food items',report.value.products,'On your menu'],['Total sales',money(report.value.total_sales),'All fulfilled orders']]);
function exportReport(){if(!report.value)return;const safe=value=>`"${String(value??'').replace(/^[=+@\-\t\r]/,"'").replaceAll('"','""')}"`;const records=[['Report',`${report.value.from} to ${report.value.to}`],['Revenue',report.value.revenue],['Orders',report.value.orders],['Cash collected',report.value.cash_collected],['Cancelled',report.value.cancelled],[],['Best seller','Quantity','Revenue'],...report.value.best_sellers.map(item=>[item.product_name,item.quantity,item.revenue])];const blob=new Blob([records.map(row=>row.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`sales-${report.value.from}-${report.value.to}.csv`;link.click();URL.revokeObjectURL(url);}
onMounted(selectRange);
</script>
<template><div><div class="admin-page-heading"><div><div class="eyebrow">A LITTLE CLARITY. A LOT OF POSSIBILITIES.</div><h1>{{ isReports ? 'Sales reports' : 'Your restaurant at a glance.' }}</h1><p>{{ isReports ? 'See what’s selling and where your business is growing.' : 'Keep an eye on the kitchen, your customers, and every delicious order.' }}</p></div><button v-if="isReports" class="button button-small" @click="exportReport" :disabled="!report || busy">Export CSV ↓</button><router-link v-else to="/admin/orders" class="button">Manage orders →</router-link></div><form class="panel report-filters" @submit.prevent="load"><label>Period<select v-model="preset" @change="selectRange"><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="month">This month</option><option value="last-month">Last month</option><option value="year">This year</option><option value="custom">Custom range</option></select></label><label>From<input v-model="from" type="date" required @input="preset='custom'"></label><label>To<input v-model="to" type="date" :min="from" required @input="preset='custom'"></label><button class="button button-small" :disabled="busy">{{ busy ? 'Loading…' : 'Apply filters' }}</button></form><div v-if="error" class="form-error" role="alert">{{ error }}</div><template v-if="report"><div class="stats-grid"><article v-for="[label,value,note] in metrics" :key="label" class="stat-card"><span>{{ label }}</span><strong>{{ value }}</strong><small>{{ note }}</small></article></div><div class="panel sales-chart-panel"><div class="section-heading"><h2>Sales over time.</h2><label class="chart-grouping">Group by<select v-model="grouping"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><span>{{ report.from }} — {{ report.to }}</span></div><p>Revenue includes delivered and completed orders, excluding cancellations.</p><div v-if="graphDays.length" class="sales-chart" role="img" aria-label="Daily fulfilled order revenue"><div v-for="day in graphDays" :key="day.date" class="chart-column" :title="`${day.date}: ${money(day.revenue)}`"><span>{{ money(day.revenue) }}</span><div class="chart-bar" :style="{height:`${Math.max(3,Number(day.revenue)/maxRevenue*160)}px`}"></div><small>{{ grouping==='monthly' ? day.date : day.date.slice(5) }}</small></div></div><div v-else class="empty-inline">The first completed order will bring this chart to life.</div></div><div class="dashboard-tables"><div class="panel"><h2>The crowd favorites.</h2><div class="table-scroll"><table><thead><tr><th>Food item</th><th>Quantity</th><th>Revenue</th></tr></thead><tbody><tr v-for="item in report.best_sellers" :key="`${item.product_id}-${item.product_name}`"><td>{{ item.product_name }}</td><td>{{ item.quantity }}</td><td>{{ money(item.revenue) }}</td></tr><tr v-if="!report.best_sellers.length"><td colspan="3">No fulfilled orders in this period.</td></tr></tbody></table></div></div><div class="panel"><h2>Your regulars.</h2><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Sales</th></tr></thead><tbody><tr v-for="customer in report.valuable_customers" :key="customer.id"><td>{{ customer.name }}</td><td>{{ money(customer.orders_sum_total) }}</td></tr><tr v-if="!report.valuable_customers.length"><td colspan="2">Your community starts here.</td></tr></tbody></table></div></div></div><div v-if="isReports" class="dashboard-tables"><div class="panel"><h2>Least ordered</h2><div class="table-scroll"><table><thead><tr><th>Food</th><th>Quantity</th><th>Revenue</th></tr></thead><tbody><tr v-for="item in report.least_sellers" :key="`${item.product_id}-${item.product_name}`"><td>{{ item.product_name }}</td><td>{{ item.quantity }}</td><td>{{ money(item.revenue) }}</td></tr></tbody></table></div></div><div class="panel"><h2>Waiting to be discovered.</h2><p v-for="item in report.unsold_products" :key="item.id">{{ item.name }}</p><p v-if="!report.unsold_products.length">Every menu item has found its fans.</p></div></div></template></div></template>
